import math

def S2(n, p):
    if n <= 0 or not (1 <= p <= n-1):
        return None
    # S2(p) = (4/n) * (p + (n-p)^(1/3) * p^(2/3))
    try:
        term_p = math.pow(n - p, 1/3) * math.pow(p, 2/3)
        return (4/n) * (p + term_p)
    except ValueError:
        # Should not happen if 1 <= p <= n-1
        return None

results = {}

# n=3
n3_results = {}
for p in range(1, 3):
    val = S2(3, p)
    n3_results[p] = val
max_n3 = max(n3_results.values())
results['n=3'] = max_n3

# n=4
n4_results = {}
for p in range(1, 4):
    val = S2(4, p)
    n4_results[p] = val
max_n4 = max(n4_results.values())
results['n=4'] = max_n4

# n=5
n5_results = {}
for p in range(1, 5):
    val = S2(5, p)
    n5_results[p] = val
max_n5 = max(n5_results.values())
results['n=5'] = max_n5

print(f"Max S2 for n=3: {results['n=3']}")
print(f"Max S2 for n=4: {results['n=4']}")
print(f"Max S2 for n=5: {results['n=5']}")
